#!/usr/bin/env python3
"""Patch the scaffold generated by ``flutter create`` into a TmuxWeb client.

Applied once after ``flutter create --platforms=android,ios --org com.tmuxweb .``
and safe to re-run (every edit is idempotent):

  * Android: INTERNET permission in the release manifest, cleartext HTTP for
    self-hosted servers, app label, applicationId.
  * iOS: display name, ATS exception for plain-HTTP self-hosted servers,
    deployment target.

Usage: python3 scripts/patch_client_platforms.py
"""

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent.parent / "client"


def patch(path: Path, edit) -> None:
    text = path.read_text()
    updated = edit(text)
    if updated != text:
        path.write_text(updated)
        print(f"patched {path.relative_to(ROOT.parent)}")
    else:
        print(f"unchanged {path.relative_to(ROOT.parent)}")


def android_manifest(text: str) -> str:
    if "android.permission.INTERNET" not in text:
        text = text.replace("<manifest ", '<manifest ', 1)
        # permissions go before <application>
        text = re.sub(r"(\n)(\s*)<application",
                      '\\1\\2<uses-permission android:name="android.permission.INTERNET"/>\\1\\2<application',
                      text, count=1)
    if 'android:usesCleartextTraffic' not in text:
        text = text.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
    text = re.sub(r'android:label="[^"]*"', 'android:label="TmuxWeb"', text, count=1)
    return text


def ios_info_plist(text: str) -> str:
    text = re.sub(r"<key>CFBundleDisplayName</key>\s*<string>[^<]*</string>",
                  "<key>CFBundleDisplayName</key>\n\t<string>TmuxWeb</string>", text, count=1)
    if "NSAppTransportSecurity" not in text:
        ats = (
            "\t<key>NSAppTransportSecurity</key>\n"
            "\t<dict>\n"
            "\t\t<!-- self-hosted servers are usually plain HTTP on a LAN -->\n"
            "\t\t<key>NSAllowsArbitraryLoads</key>\n"
            "\t\t<true/>\n"
            "\t</dict>\n"
            "</dict>\n</plist>"
        )
        text = text.replace("</dict>\n</plist>", ats, 1)
    return text


def gradle_signing(text: str) -> str:
    """Optional release keystore: only used when android/key.properties exists."""
    if "keystorePropertiesFile" in text:
        return text
    text = text.replace("plugins {\n    id(\"com.android.application\")",
                        "import java.io.FileInputStream\nimport java.util.Properties\n\nplugins {\n    id(\"com.android.application\")", 1)
    text = text.replace("android {\n    namespace",
                        "// Release signing is optional: android/key.properties (never committed) enables it.\n"
                        "val keystoreProperties = Properties()\n"
                        "val keystorePropertiesFile = rootProject.file(\"key.properties\")\n"
                        "if (keystorePropertiesFile.exists()) {\n"
                        "    FileInputStream(keystorePropertiesFile).use { keystoreProperties.load(it) }\n"
                        "}\n\n"
                        "android {\n    namespace", 1)
    text = text.replace(
        '    buildTypes {\n        release {\n            // TODO: Add your own signing config for the release build.\n'
        '            // Signing with the debug keys for now, so `flutter run --release` works.\n'
        '            signingConfig = signingConfigs.getByName("debug")\n        }\n    }',
        '    signingConfigs {\n        if (keystorePropertiesFile.exists()) {\n            create("release") {\n'
        '                keyAlias = keystoreProperties["keyAlias"] as String\n'
        '                keyPassword = keystoreProperties["keyPassword"] as String\n'
        '                storeFile = rootProject.file(keystoreProperties["storeFile"] as String)\n'
        '                storePassword = keystoreProperties["storePassword"] as String\n'
        '            }\n        }\n    }\n\n    buildTypes {\n        release {\n'
        '            signingConfig = if (keystorePropertiesFile.exists()) {\n'
        '                signingConfigs.getByName("release")\n'
        '            } else {\n                signingConfigs.getByName("debug")\n            }\n        }\n    }', 1)
    return text


def main() -> None:
    manifest = ROOT / "android" / "app" / "src" / "main" / "AndroidManifest.xml"
    if manifest.exists():
        patch(manifest, android_manifest)
    else:
        print("missing AndroidManifest.xml (run flutter create first)")

    gradle = ROOT / "android" / "app" / "build.gradle.kts"
    if gradle.exists():
        patch(gradle, gradle_signing)

    plist = ROOT / "ios" / "Runner" / "Info.plist"
    if plist.exists():
        patch(plist, ios_info_plist)
    else:
        print("missing ios/Runner/Info.plist (run flutter create first)")


if __name__ == "__main__":
    main()
